const reviewReason = valid
  ? [base.review_reason, 'draft_ready_human_approval_required'].filter(Boolean).join('; ')
  : [base.review_reason, ...reasons, 'escalate_to_human_no_auto_send'].filter(Boolean).join('; ');
return { json: {
  ...base,
  status,
  status_html: htmlEscape(status),
  intent,
