  draft_reply: valid ? draftReply : '',
  draft_reply_html: htmlEscape(valid ? draftReply : ''),
  review_reason: reviewReason,
  review_reason_html: htmlEscape(reviewReason),
  kb_confidence: Math.min(base.kb_confidence || 0, confidence || 0),
  ai_raw_json: JSON.stringify({ parsedFrom, ai }).slice(0, 9000),
  validation_errors: reasons.join('; '),
  updated_at: new Date().toISOString(),
} };

