  canonical_question: canonicalQuestion,
  canonical_question_html: htmlEscape(canonicalQuestion),
  approved_answer: approval.approved_reply,
  approved_answer_html: approval.approved_reply_html,
  approved_by: approval.approved_by,
  approval_action: approval.action,
  confidence: Number(row.kb_confidence || 0),
  metadata_json: JSON.stringify({
    source: 'support_human_approved_support_reply',
    captured_only_after_send: true,
    canonical_question_source: row.matched_kb_id && kbCanonicalQuestions[row.matched_kb_id] ? 'kb_canonical_question' : 'kb_title_or_intent_fallback',
    customer_freeform_question_stored: false,
    prompt_injection_observed: Boolean(row.prompt_injection_observed),
    original_ticket_status: row.status || '',
  }),
  created_at: new Date().toISOString(),
} };

const row = $('Find Review Ticket Row').item.json || {};
const approval = $('Normalize Support Approval').item.json;
return { json: {
  id: row.id || '',
  status: approval.action === 'reject' ? 'Rejected' : 'Escalated',
  approved_action: approval.action,
  approved_reply: '',
  approved_reply_html: '',
  approved_by: approval.approved_by,
  learning_capture_allowed: false,
  sent_email_id: '',
  updated_at: new Date().toISOString(),
  last_execution_id: approval.last_execution_id,
} };

const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const boolish = (value) => value === true || String(value).toLowerCase() === 'true' || String(value) === '1';
const subjectText = (value) => String(value ?? '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 180);
const eligible = new Set(['Draft Ready', 'Escalated']);
return $input.all().flatMap((item, index) => {
  const row = item.json || {};
  const status = String(row.status || '');
  if (!row.id || !eligible.has(status) || boolish(row.review_alert_sent)) return [];
  const ticketKey = subjectText(row.ticket_key || 'unknown-ticket');
  const queue = status === 'Draft Ready' ? 'HUMAN_REVIEW' : 'HUMAN_ESCALATION';
  const messageHtml = [
    '<p><strong>Support review alert retry</strong></p>',
    '<p>Queue: ' + htmlEscape(queue) + '</p>',
    '<p>Ticket: ' + htmlEscape(ticketKey) + '</p>',
    '<p>Record: ' + htmlEscape(row.id) + '</p>',
    '<p>Status: ' + htmlEscape(status) + '</p>',
    '<p>Intent: ' + htmlEscape(row.intent || 'Other') + '</p>',
    '<p>Question: ' + htmlEscape(row.question_summary || '') + '</p>',
    '<p>KB source: ' + htmlEscape(row.matched_kb_title || row.matched_kb_id || '') + '</p>',
    '<p>Draft: ' + htmlEscape(row.draft_reply || '') + '</p>',
    '<p>Review reason: ' + htmlEscape(row.review_reason || row.validation_errors || '') + '</p>',
    '<p>Security flags: ' + htmlEscape(row.security_flags || '') + '</p>',
  ].join('');
  return [{ json: { id: row.id, subject: '[TEST] Support review retry: ' + ticketKey, message_html: messageHtml }, pairedItem: { item: index } }];
});

const alert = $input.item.json || {};
const messageId = String(alert.id || alert.messageId || alert.message_id || '').trim();
if (!messageId) throw new Error('support_review_alert_missing_message_id');
const row = $('Build Unsent Support Review Alert').item.json;
return { json: { id: row.id, review_alert_sent: true, review_alert_id: messageId, updated_at: new Date().toISOString(), last_execution_id: $execution.id } };
